import sys

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    if n > m:
        n, m = m, n

    dimension = 1 << n
    dynamic = [[1000000000 for _ in range(dimension)] for _ in range(dimension)]
    for row in dynamic:
        row[0] = 0

    for stepCount in range(m):
        newState = [[1000000000 for _ in range(dimension)] for _ in range(dimension)]
        for prevMask in range(dimension):
            for currMask in range(dimension):
                if dynamic[prevMask][currMask] != 1000000000:
                    limit = 1 if stepCount == m - 1 else dimension
                    for nextMask in range(limit):
                        coveredBits = 0
                        for bit in range(n):
                            if ((1 << bit) & currMask) == 0:
                                above = bit - 1
                                below = bit + 1
                                if above >= 0 and ((1 << above) & currMask) != 0:
                                    coveredBits |= 1 << bit
                                if below < n and ((1 << below) & currMask) != 0:
                                    coveredBits |= 1 << bit
                                if ((1 << bit) & prevMask) != 0:
                                    coveredBits |= 1 << bit
                                if ((1 << bit) & nextMask) != 0:
                                    coveredBits |= 1 << bit
                        costVal = dynamic[prevMask][currMask] + n - bin(coveredBits).count('1')
                        if costVal < newState[currMask][nextMask]:
                            newState[currMask][nextMask] = costVal
        dynamic = newState

    minVal = 1000000000
    for row in dynamic:
        for val in row:
            if val < minVal:
                minVal = val
    print(n * m - minVal)

